for p in (W/'commentary').glob('*.md'):
 s=p.read_text()
 def sub(m):return '=== '+m[1]+'\n\n'+new[m[1]]+'\n\n' if m[1] in new else m[0]
 t=re.sub(r'^=== (\S+)\s*\n(.*?)(?=^=== |\Z)',sub,s,flags=re.S|re.M)
 if t!=s:p.write_text(t)
